	return Promise.allSettled([
		signUpUser(firstname, lastname),
		uploadPhoto(filename),
	]).then((results) => results.map((results) => ({
		status: results.status,
		value: results.status === 'fulfilled'
		? results.value
		: results.reason,
	}))
);
}

